import test from 'node:test';
import assert from 'node:assert/strict';
import { deflateSync, constants } from 'node:zlib';
import { verifyGitBundleObjects } from '../../crates/fgit-node/src/smart_http/server/browser/bundle-verify.mjs';
import { bytes, bundle, literalDelta, objectId, webcrypto } from './bundle-verify-fixtures.mjs';
const verify = (input, options = {}) => verifyGitBundleObjects(input, { cryptoImpl: webcrypto, ...options });
// Independent bit-level vectors, not bytes generated by the implementation.
class Writer {
  out = []; value = 0; count = 0;
  bits(value, count) { for (let n = 0; n < count; n++) { this.value |= ((value >>> n) & 1) << this.count++; if (this.count === 8) { this.out.push(this.value); this.value = 0; this.count = 0; } } return this; }
  code(value, count) { for (let n = count - 1; n >= 0; n--) this.bits((value >>> n) & 1, 1); return this; }
  zlib(adler = 1) { if (this.count) this.out.push(this.value); const checksum = Buffer.alloc(4); checksum.writeUInt32BE(adler); return Buffer.concat([bytes([0x78, 0x9c, ...this.out]), checksum]); }
}
function fixed(symbols) {
  const writer = new Writer().bits(1, 1).bits(1, 2);
  for (const [kind, value] of symbols) {
    if (kind === 'distance') writer.code(value, 5);
    else if (value < 144) writer.code(48 + value, 8);
    else if (value < 256) writer.code(400 + value - 144, 9);
    else if (value < 280) writer.code(value - 256, 7);
    else writer.code(192 + value - 280, 8);
  }
  return writer;
}
for (const [name, symbols, code] of [
  ['reserved literal 286', [['literal', 286]], 'reserved_length_code'],
  ['reserved literal 287', [['literal', 287]], 'reserved_length_code'],
  ['reserved distance 30', [['literal', 257], ['distance', 30]], 'reserved_distance_code'],
  ['reserved distance 31', [['literal', 257], ['distance', 31]], 'reserved_distance_code'],
  ['distance before output', [['literal', 257], ['distance', 0]], 'invalid_back_reference'],
]) test(`bit-level DEFLATE refuses ${name}`, async () => {
  const input = bundle([{ body: bytes(''), zlib: fixed(symbols).zlib() }]);
  await assert.rejects(verify(input), error => error.code === code);
});
function dynamic(lengths) {
  const writer = new Writer().bits(1, 1).bits(2, 2).bits(0, 5).bits(0, 5).bits(0, 4);
  for (const value of lengths) writer.bits(value, 3); return writer;
}
for (const [lengths, code] of [
  [[1, 1, 1, 0], 'oversubscribed_huffman_tree'],
  [[2, 0, 0, 0], 'incomplete_huffman_tree'],
  [[0, 0, 0, 0], 'empty_huffman_tree'],
]) test(`bit-level dynamic tree refuses ${code}`, async () => {
  await assert.rejects(verify(bundle([{ body: bytes(''), zlib: dynamic(lengths).zlib() }])), error => error.code === code);
});
test('a repeated code length cannot borrow an absent predecessor', async () => {
  const zlib = dynamic([1, 1, 0, 0]).code(0, 1).zlib();
  await assert.rejects(verify(bundle([{ body: bytes(''), zlib }])), error => error.code === 'missing_repeated_code_length');
});
test('code-length runs cannot overflow the combined literal/distance alphabet', async () => {
  const zlib = dynamic([0, 0, 1, 1]).code(1, 1).bits(127, 7).code(1, 1).bits(127, 7).zlib();
  await assert.rejects(verify(bundle([{ body: bytes(''), zlib }])), error => error.code === 'code_length_repeat_overflow');
});
test('the literal alphabet must contain an end-of-block code', async () => {
  const zlib = dynamic([0, 0, 1, 1]).code(1, 1).bits(127, 7).code(1, 1).bits(109, 7).zlib();
  await assert.rejects(verify(bundle([{ body: bytes(''), zlib }])), error => error.code === 'missing_end_of_block');
});
test('seeded varied byte corpora agree with independent zlib encoders in every strategy', async () => {
  let state = 0x731ca579;
  const random = () => { state ^= state << 13; state ^= state >>> 17; state ^= state << 5; return state >>> 0; };
  for (let n = 0; n < 160; n++) {
    const body = Buffer.alloc(n < 5 ? n : random() % 6000);
    for (let i = 0; i < body.length; i++) body[i] = n % 4 === 0 ? random() % 256 : n % 4 === 1 ? i % 251 : n % 4 === 2 ? random() % 4 : 65;
    const zlib = deflateSync(body, { level: [0, 1, 6, 9][n % 4], strategy: [constants.Z_DEFAULT_STRATEGY, constants.Z_FILTERED, constants.Z_HUFFMAN_ONLY, constants.Z_RLE, constants.Z_FIXED][n % 5], windowBits: n % 2 ? 9 : 15 });
    const report = await verify(bundle([{ body, zlib }])); assert.equal(report.refs[0].object_id, objectId('blob', body));
  }
});
test('delta chains at depth 64 pass while depth 65 refuses before reconstruction', async () => {
  const rows = [{ body: bytes([0]) }]; let prior = rows[0].body;
  for (let n = 1; n <= 65; n++) { const next = bytes([n]); rows.push({ type: 6, base: n - 1, body: literalDelta(prior, next) }); prior = next; }
  const input = bundle(rows.slice(0, 65), 'sha1', { refs: [{ name: 'refs/tags/end', id: objectId('blob', bytes([64])) }] });
  assert.equal((await verify(input)).maximum_delta_depth, 64);
  await assert.rejects(verify(bundle(rows, 'sha1', { refs: [{ name: 'refs/tags/end', id: objectId('blob', prior) }] })), error => error.code === 'delta_depth_limit');
});
